async def execute_specialist(
    agent_id,
    task_id,
    worker,
    inputs
):

    with tracer.start_as_current_span(
        "agent.execute",
        record_exception=False,
        set_status_on_exception=False
    ) as span:

        span.set_attribute(
            "app.agent.id",
            agent_id
        )

        span.set_attribute(
            "app.task.id",
            task_id
        )

        try:

            result = await worker(inputs)

            span.set_attribute(
                "app.execution.outcome",
                "returned"
            )

            return result

        except Exception as exc:

            span.set_attribute(
                "error.type",
                type(exc).__name__
            )

            span.set_status(
                Status(StatusCode.ERROR)
            )

            raise

